// Fim dos Tempos · Arco 2 · As Ruas Traiçoeiras de Valkaria · gerado por a2-ruas-valkaria.js
const DADOS = {"juramento":["Eu juro, por Khalmyr e pela Rainha-Imperatriz","Defender a cidade, e o povo acima dela","Honrar meus companheiros, e a lei acima deles","Buscar em todos os casos a verdade, e a justiça acima disso","Zelar pela ordem, e pela vida acima de tudo","Colocar o dever acima de mim mesmo","E, acima do dever, o bem"],"direitos":"Você é acusado de {crime} pela Guarda de Valkaria, sob a verdade de Khalmyr e Tanna-Toh. Você está sob responsabilidade da cidade de Valkaria e tem o direito de ser alimentado e abrigado. Tem o direito de receber a visita de um clérigo de qualquer deus do qual for devoto, desde que não represente perigo ou profanação. Tem o direito de estar a salvo de qualquer controle mental, leitura de pensamentos ou vigilância de sua alma. Ao aceitar esses direitos, reconhece ser um habitante inteligente e não monstruoso do mundo material, sujeito às leis dos mortais.","forca":[["Presença e ordens verbais","O primeiro nível de força, pela cartilha que existe há séculos: \"Guarda de Valkaria! Parado!\""],["Técnicas não letais","Se o suspeito resiste, mas não é violento nem está armado."],["Força letal","Só se o suspeito ataca o guarda ou outra pessoa. Mesmo assim, o juramento manda se esforçar para não matar. Todo guarda deve fazer um esforço real para capturar suspeitos com vida."]],"punicoes":[["Infrações simples","Danos materiais, descumprir ordem direta (\"Eu falei para vocês não se meterem com o barão!\"), equipamento ilegal: uma ou duas semanas de afastamento e suspensão do pagamento do caso resolvido de forma irregular. O guarda entrega espada e distintivo e, teoricamente, se afasta de todos os assuntos da Guarda (por alguma razão, isso raramente é cumprido). Investigadas por outra guarita ou punidas de forma simples."],["Desrespeito flagrante às autoridades","Prosseguir numa investigação encerrada, invadir propriedade sem autorização, usar magia ilegal num suspeito, mesmo com as melhores intenções: expulsão e perda de aposentadoria (curiosamente, uma ameaça que aflige muitos guardas prestes a se aposentar)."],["Crimes","Execuções, acusações falsas e chantagem: investigação detalhada, expulsão e/ou qualquer pena cabível. A Rocha Cinzenta é um lugar terrível para ex-guardas."]],"cargos":[["Dama da Justiça","Xarynn Libra, eleita pelos Lordes Urbanos. Chefia toda a Guarda."],["Reguladores","Figurões de um conselho, sob a vigilância dos Juízes de Khalmyr. Cada Xerife responde a um Regulador."],["Xerife","Comanda uma guarita com bastante autonomia, dentro das regras básicas da Guarda. Escolhe os detetives e a prioridade dos casos."],["Detetives","Investigam cenas de crime, suspeitos, desaparecidos e casos de todo tipo. Quase aventureiros a serviço da Guarda; agem em duplas ou equipes. Não fazem rondas nem portam apito. Ganham por caso resolvido no mês: quanto mais provas, mais o caso rende. Heróis de confiança podem receber o posto honorário."],["Alcaides","Comandantes de equipes de patrulha (portões, áreas de patrulha intensa). Mesmo nível dos detetives, mas em geral não ascendem."],["Patrulheiros","O posto mais baixo e o maior contingente: rondas em duplas ou pequenos grupos, apito, primeiros a responder. Salário fixo da cidade; rodam entre guaritas. Chamam detetives para todo crime que não viram com os próprios olhos."],["Guarda do Palácio","Protege o Palácio Imperial e arredores, com prestígio e pouquíssima liberdade. Nunca atua em outras áreas."],["Guarda Arcana","Arcanistas, clérigos, inventores e outros: magia de adivinhação nas cenas, traços mágicos, pesquisa e, recentemente, autópsias. Raramente entram na ação."]]};
(async function macroGuarda(D) {
		const res = await foundry.applications.api.DialogV2.prompt({
			window: { title: "Guarda · Juramento e Direitos" },
			position: { width: 480 },
			content: `
				<div class="form-group"><label>O que mostrar</label><select name="acao">
					<option value="juramento">Juramento da Guarda (os selecionados juram)</option>
					<option value="direitos">Direitos dos Suspeitos (ao prender alguém)</option>
					<option value="forca">Níveis de força permitidos</option>
					<option value="punicoes">Punições a guardas</option>
					<option value="cargos">Quem é quem na Guarda</option></select></div>
				<div class="form-group"><label>Crime do suspeito (para os direitos)</label><input type="text" name="crime" placeholder="roubo de um item mágico"></div>`,
			ok: { label: "Mostrar", callback: (ev, button) => Object.fromEntries(new FormData(button.form)) }
		});
		if (!res) return;
		const lista = (pares) => `<ul>${pares.map(([t, d]) => `<li><b>${t}.</b> ${d}</li>`).join("")}</ul>`;
		let html = "";
		if (res.acao === "juramento") {
			const quem = canvas.tokens?.controlled.map((t) => t.name) ?? [];
			html = `<h3>Juramento da Guarda de Valkaria</h3>${quem.length ? `<p><i>Juram: ${quem.join(", ")}.</i></p>` : ""}<blockquote>${D.juramento.join("<br>")}</blockquote>`;
		} else if (res.acao === "direitos") {
			const crime = String(res.crime ?? "").trim() || "(crime do qual o suspeito é acusado)";
			html = `<h3>Direitos dos Suspeitos</h3><blockquote>“${D.direitos.replace("{crime}", crime)}”</blockquote>`;
		} else if (res.acao === "forca") {
			html = `<h3>Ninguém Acima da Lei: níveis de força</h3>${lista(D.forca)}<p>Ao capturar, recite os direitos. Suspeitos são interrogados; quem é pego em flagrante passa aos Juízes de Khalmyr, e os guardas só fornecem provas e testemunhas. Depois, relatórios e papelada.</p>`;
		} else if (res.acao === "punicoes") {
			html = `<h3>Punições a guardas</h3>${lista(D.punicoes)}`;
		} else {
			html = `<h3>Quem é quem na Guarda</h3>${lista(D.cargos)}`;
		}
		await ChatMessage.create({ content: html });
	})(DADOS);
